INSERT INTO knowledge_drift_events(
    id,repo_id,card_id,card_revision,from_snapshot_id,to_snapshot_id,from_commit,to_commit,
    previous_status,result_status,trigger_type,reasons_payload,note,actor_id,created_at
) VALUES(
    #{id},#{repositoryId},#{cardId},#{cardRevision},#{fromSnapshotId},#{toSnapshotId},
    #{fromCommit},#{toCommit},#{previousStatus},#{resultStatus},#{triggerType},
    CAST(#{reasonsPayload} AS jsonb),#{note},#{actorId},#{createdAt}
) ON CONFLICT DO NOTHING
